// ---------------------------------------------------------------------------
// Hostnames
// ---------------------------------------------------------------------------
const LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

function isValidHostname(value) {
  if (typeof value !== 'string' || value.length === 0 || value.length > 253) return false;
  if (value !== value.toLowerCase()) return false;
