  const octets = [];
  for (const p of parts) {
    // sem zeros à esquerda (evita ambiguidade octal) e só dígitos
    if (!/^(?:0|[1-9][0-9]{0,2})$/.test(p)) return null;
    const n = Number(p);
    if (n > 255) return null;
    octets.push(n);
  }
  return octets;
