function ipv4ToInt(o) {
  return ((o[0] << 24) >>> 0) + (o[1] << 16) + (o[2] << 8) + o[3];
}

function ipv4InRange(octets, range) {
  const mask = range.bits === 0 ? 0 : (0xffffffff << (32 - range.bits)) >>> 0;
  return ((ipv4ToInt(octets) & mask) >>> 0) === ((ipv4ToInt(range.base) & mask) >>> 0);
