function ipv6InPrefix(groups, prefix) {
  let bits = prefix.bits;
  for (let i = 0; i < 8 && bits > 0; i++) {
    const take = Math.min(16, bits);
    const mask = (0xffff << (16 - take)) & 0xffff;
    if ((groups[i] & mask) !== (prefix.groups[i] & mask)) return false;
    bits -= take;
