// Extração de texto do card (Atlassian Document Format) e leitura de campos
// estruturados no formato "Chave: valor", um por linha.

const MAX_TEXT_LENGTH = 20000;

function adfToText(node) {
  if (node == null) return '';
  if (typeof node === 'string') return node.slice(0, MAX_TEXT_LENGTH);
  const out = [];
  const walk = (n) => {
    if (!n || typeof n !== 'object') return;
    if (n.type === 'text' && typeof n.text === 'string') out.push(n.text);
    if (n.type === 'hardBreak') out.push('\n');
    if (Array.isArray(n.content)) n.content.forEach(walk);
    if (['paragraph', 'heading', 'listItem', 'codeBlock', 'blockquote'].includes(n.type)) out.push('\n');
  };
  walk(node);
  return out.join('').replace(/\n{3,}/g, '\n\n').trim().slice(0, MAX_TEXT_LENGTH);
}

function normalizeKey(value) {
  return String(value)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

// Nome canônico do campo -> variações aceitas no template do card
const FIELD_ALIASES = {
  cliente: ['cliente', 'contacpanel', 'usuariocpanel', 'usuario'],
  ip: ['ip', 'enderecoip', 'ipbloqueado'],
  email: ['email', 'contadeemail', 'caixapostal', 'conta'],
  atividade: ['atividade', 'tipo', 'tipodeatividade'],
  periodo: ['periodo'],
};

const ALIAS_TO_FIELD = Object.entries(FIELD_ALIASES).reduce((acc, [field, aliases]) => {
  aliases.forEach((a) => { acc[a] = field; });
  return acc;
}, {});

/**
 * Lê linhas "Chave: valor". Só campos conhecidos são considerados; um campo
 * repetido com valores diferentes é marcado como ambíguo (o card é recusado).
 */
function parseFields(text) {
  const fields = {};
  const ambiguous = new Set();
  String(text || '').split(/\r?\n/).forEach((line) => {
    const m = line.match(/^\s*[-*]?\s*([^:]{1,40}):\s*(.{1,320}?)\s*$/);
    if (!m) return;
    const field = ALIAS_TO_FIELD[normalizeKey(m[1])];
    if (!field) return;
    const value = m[2].trim();
    if (fields[field] !== undefined && fields[field] !== value) ambiguous.add(field);
    else fields[field] = value;
  });
  return { fields, ambiguous: [...ambiguous] };
}

function normalizeText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();
}

// ---- src/jira.js ----
// Helpers de Jira Cloud REST v3: consulta (JQL), comentário em ADF e transição.


function jqlQuote(value) {
  return '"' + String(value).replace(/["\\]/g, '\\$&') + '"';
}

function buildSearchRequest(cfg) {
  const projects = cfg.projectKeys.filter((k) => /^[A-Z][A-Z0-9_]{1,9}$/.test(k));
  if (!projects.length) throw new Error('jira: nenhuma chave de projeto válida');
  const jql = [
    'project IN (' + projects.join(', ') + ')',
    'status = ' + jqlQuote(cfg.automationStatus),
    '(labels IS EMPTY OR labels NOT IN (' + jqlQuote(cfg.claimLabel) + '))',
  ].join(' AND ') + ' ORDER BY created ASC';
  return {
    jql,
    maxResults: cfg.searchMaxResults,
    fields: ['summary', 'description', 'status', 'labels', 'reporter', 'issuetype', 'attachment'],
    expand: 'changelog',
  };
}

/** Texto simples -> documento ADF (um parágrafo por linha; sem marcação vinda de fora). */
function buildAdfDoc(text) {
  const lines = String(text || '').split('\n').slice(0, 50);
  return {
    type: 'doc',
    version: 1,
    content: lines.map((line) => (line
      ? { type: 'paragraph', content: [{ type: 'text', text: line.slice(0, 1000) }] }
      : { type: 'paragraph', content: [] })),
  };
}

function pickTransition(transitions, targetStatus) {
  const target = normalizeText(targetStatus);
  return (transitions || []).find((t) => normalizeText(t.to && t.to.name) === target) ||
    (transitions || []).find((t) => normalizeText(t.name) === target) ||
    null;
}

/** Normaliza itens vindos do planejador (recusa) ou do resultado da execução. */
function toJiraUpdate(item) {
  return {
    issueKey: item.issueKey,
    adf: buildAdfDoc(item.jiraComment),
    targetStatus: item.targetStatus,
    audit: item.audit,
  };
}

// ---- cola do nó ----
return { json: toJiraUpdate($json) };

